THREE_JS_B64 = ""

ORBIT_CONTROLS_JS = r"""
// =========================================================================
// Standalone OrbitControls for Three.js (r128)
// =========================================================================
(function() {
  if (typeof THREE === 'undefined') return;

  THREE.OrbitControls = function(object, domElement) {
    this.object = object;
    this.domElement = (domElement !== undefined) ? domElement : document;
    this.enabled = true;
    this.target = new THREE.Vector3();

    this.minDistance = 5.0;
    this.maxDistance = 50.0;

    this.minPolarAngle = 0.05;
    this.maxPolarAngle = Math.PI - 0.05;

    this.enableDamping = true;
    this.dampingFactor = 0.08;

    this.rotateSpeed = 1.0;
    this.zoomSpeed = 1.2;

    this.autoRotate = false;
    this.autoRotateSpeed = 2.0;

    const scope = this;
    const STATE = { NONE: -1, ROTATE: 0, DOLLY: 1 };
    let state = STATE.NONE;

    const spherical = { radius: 24, phi: Math.PI / 4, theta: Math.PI / 4 };
    const sphericalDelta = { radius: 0, phi: 0, theta: 0 };

    const rotateStart = new THREE.Vector2();
    const rotateEnd = new THREE.Vector2();
    const rotateDelta = new THREE.Vector2();

    const initialPosition = object.position.clone();
    const initialTarget = this.target.clone();

    function updateSphericalFromObject() {
      const offset = object.position.clone().sub(scope.target);
      spherical.radius = offset.length();
      if (spherical.radius === 0) {
        spherical.radius = 24;
        spherical.theta = 0;
        spherical.phi = 0;
      } else {
        spherical.phi = Math.acos(Math.max(-1, Math.min(1, offset.y / spherical.radius)));
        spherical.theta = Math.atan2(offset.x, offset.z);
      }
    }
    updateSphericalFromObject();

    this.update = function() {
      if (scope.autoRotate && state === STATE.NONE) {
        sphericalDelta.theta += 0.005 * scope.autoRotateSpeed;
      }

      if (scope.enableDamping) {
        spherical.theta += sphericalDelta.theta * scope.dampingFactor;
        spherical.phi += sphericalDelta.phi * scope.dampingFactor;
        spherical.radius += sphericalDelta.radius * scope.dampingFactor;

        sphericalDelta.theta *= (1 - scope.dampingFactor);
        sphericalDelta.phi *= (1 - scope.dampingFactor);
        sphericalDelta.radius *= (1 - scope.dampingFactor);
      } else {
        spherical.theta += sphericalDelta.theta;
        spherical.phi += sphericalDelta.phi;
        spherical.radius += sphericalDelta.radius;

        sphericalDelta.theta = 0;
        sphericalDelta.phi = 0;
        sphericalDelta.radius = 0;
      }

      spherical.phi = Math.max(scope.minPolarAngle, Math.min(scope.maxPolarAngle, spherical.phi));
      spherical.radius = Math.max(scope.minDistance, Math.min(scope.maxDistance, spherical.radius));

      const sinPhi = Math.sin(spherical.phi);
      const x = spherical.radius * sinPhi * Math.sin(spherical.theta);
      const y = spherical.radius * Math.cos(spherical.phi);
      const z = spherical.radius * sinPhi * Math.cos(spherical.theta);

      scope.object.position.set(scope.target.x + x, scope.target.y + y, scope.target.z + z);
      scope.object.lookAt(scope.target);
    };

    this.reset = function() {
      scope.target.copy(initialTarget);
      scope.object.position.copy(initialPosition);
      sphericalDelta.theta = 0;
      sphericalDelta.phi = 0;
      sphericalDelta.radius = 0;
      updateSphericalFromObject();
      scope.update();
    };

    this.setCameraPreset = function(posX, posY, posZ, tarX, tarY, tarZ) {
      scope.target.set(tarX || 0, tarY || 0, tarZ || 0);
      scope.object.position.set(posX, posY, posZ);
      sphericalDelta.theta = 0;
      sphericalDelta.phi = 0;
      sphericalDelta.radius = 0;
      updateSphericalFromObject();
      scope.update();
    };

    function onPointerDown(event) {
      if (!scope.enabled) return;
      if (event.button === 0) {
        state = STATE.ROTATE;
        rotateStart.set(event.clientX, event.clientY);
        scope.domElement.style.cursor = 'grabbing';
      }
    }

    function onPointerMove(event) {
      if (!scope.enabled || state !== STATE.ROTATE) return;
      rotateEnd.set(event.clientX, event.clientY);
      rotateDelta.subVectors(rotateEnd, rotateStart);

      const element = scope.domElement;
      const factorX = (2 * Math.PI) / element.clientWidth;
      const factorY = Math.PI / element.clientHeight;

      const dTheta = -rotateDelta.x * factorX * scope.rotateSpeed;
      const dPhi = -rotateDelta.y * factorY * scope.rotateSpeed;

      if (scope.enableDamping) {
        sphericalDelta.theta += dTheta;
        sphericalDelta.phi += dPhi;
      } else {
        spherical.theta += dTheta;
        spherical.phi += dPhi;
      }
      rotateStart.copy(rotateEnd);
    }

    function onPointerUp() {
      if (state === STATE.ROTATE) {
        scope.domElement.style.cursor = 'default';
      }
      state = STATE.NONE;
    }

    function onWheel(event) {
      if (!scope.enabled) return;
      event.preventDefault();
      const zoomScale = event.deltaY > 0 ? 1.08 : 0.92;
      const newRadius = spherical.radius * zoomScale;
      const dRadius = newRadius - spherical.radius;

      if (scope.enableDamping) {
        sphericalDelta.radius += dRadius;
      } else {
        spherical.radius = newRadius;
      }
    }

    let touchStartDist = 0;
    function onTouchStart(e) {
      if (!scope.enabled) return;
      if (e.touches.length === 1) {
        state = STATE.ROTATE;
        rotateStart.set(e.touches[0].pageX, e.touches[0].pageY);
      } else if (e.touches.length === 2) {
        state = STATE.DOLLY;
        const dx = e.touches[0].pageX - e.touches[1].pageX;
        const dy = e.touches[0].pageY - e.touches[1].pageY;
        touchStartDist = Math.sqrt(dx * dx + dy * dy);
      }
    }

    function onTouchMove(e) {
      if (!scope.enabled) return;
      if (state === STATE.ROTATE && e.touches.length === 1) {
        rotateEnd.set(e.touches[0].pageX, e.touches[0].pageY);
        rotateDelta.subVectors(rotateEnd, rotateStart);
        const factorX = (2 * Math.PI) / scope.domElement.clientWidth;
        const factorY = Math.PI / scope.domElement.clientHeight;
        sphericalDelta.theta -= rotateDelta.x * factorX * scope.rotateSpeed;
        sphericalDelta.phi -= rotateDelta.y * factorY * scope.rotateSpeed;
        rotateStart.copy(rotateEnd);
      } else if (state === STATE.DOLLY && e.touches.length === 2) {
        const dx = e.touches[0].pageX - e.touches[1].pageX;
        const dy = e.touches[0].pageY - e.touches[1].pageY;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const factor = touchStartDist / (dist || 1);
        sphericalDelta.radius += (spherical.radius * factor - spherical.radius) * 0.1;
        touchStartDist = dist;
      }
    }

    function onTouchEnd() {
      state = STATE.NONE;
    }

    this.domElement.addEventListener('pointerdown', onPointerDown);
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
    this.domElement.addEventListener('wheel', onWheel, { passive: false });
    this.domElement.addEventListener('touchstart', onTouchStart, { passive: false });
    window.addEventListener('touchmove', onTouchMove, { passive: false });
    window.addEventListener('touchend', onTouchEnd);
  };
})();
"""

